import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"🔬 科学快报 | 2026年7月19日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-19.md","filePath":"science-log/src/reconstructed/2026-07-19.md"}'),n={name:"science-log/src/reconstructed/2026-07-19.md"};function i(s,e,l,c,h,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年7月19日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月19日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月19日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月19日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05 ⚠️ 补充说明：2026-07-19 为<strong>周日</strong>，Nature / Science / PNAS 当日<strong>均无新刊发布</strong>（CrossRef 各库当日命中数均为 0）。故科学前沿 5 篇取自<strong>最近一期</strong>：Science 2026-07-16 期、Nature 2026-07-15 期；AI 前沿 5 篇为 arXiv cs.AI <strong>2026-07-19 当日</strong>投稿。</p></blockquote><hr><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="⚡-单电子存储器-一个电子改写阈值电压-0-5-v" tabindex="-1">⚡ 单电子存储器：一个电子改写阈值电压 0.5 V <a class="header-anchor" href="#⚡-单电子存储器-一个电子改写阈值电压-0-5-v" aria-label="Permalink to &quot;⚡ 单电子存储器：一个电子改写阈值电压 0.5 V&quot;">​</a></h3><p><strong>Robust single-electron memory with quantum states manipulation</strong><em>Science (2026)</em></p><p>信息存储的终极目标是单电子存储，但器件尺寸缩小时寄生边缘电容反而被放大，使单电子存储长期停留在理论。复旦大学刘春森、周鹏团队改用「漏—沟道—源共面」的二维器件结构压制边缘电容，实现单个电子进出即带来 0.5 V 的非易失阈值电压漂移。围绕编程电压他们还验证了两种量子行为，并预测且观测到一种新奇的量子存储效应——量子态被「态密度剪刀」截断。这是把存储的信息单元从「电荷量」压缩到「电荷的量子态」的关键一步。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aeg6638" target="_blank" rel="noreferrer">10.1126/science.aeg6638</a></p><h3 id="🔬-几何而非体积决定-原子尺度可逆固—液相变" tabindex="-1">🔬 几何而非体积决定：原子尺度可逆固—液相变 <a class="header-anchor" href="#🔬-几何而非体积决定-原子尺度可逆固—液相变" aria-label="Permalink to &quot;🔬 几何而非体积决定：原子尺度可逆固—液相变&quot;">​</a></h3><p><strong>Geometrically driven reversible solid-liquid phase transition at the atomic scale</strong><em>Science (2026)</em></p><p>武汉理工大学（与安特卫普大学合作）团队用原位透射电镜，把一颗临界尺寸的铋纳米团簇夹在可调纳米间隙中，直接驱动它完成「准非晶纳米盘 → 晶体纳米线 → 液体纳米滴」的可逆循环。结果显示控制相变的第一描述符是团簇的<strong>长径比</strong>而不是体积，背后是本征表面各向异性与界面能的竞争；几何限域还强迫纳米线采用特定取向的织构。这为异质形核提供了一个可在原子分辨率下逐帧观察、且可正反向操作的模型体系。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aed6019" target="_blank" rel="noreferrer">10.1126/science.aed6019</a></p><h3 id="🔌-越细越导电-weyl-半金属-nbas-纳米线互连" tabindex="-1">🔌 越细越导电：Weyl 半金属 NbAs 纳米线互连 <a class="header-anchor" href="#🔌-越细越导电-weyl-半金属-nbas-纳米线互连" aria-label="Permalink to &quot;🔌 越细越导电：Weyl 半金属 NbAs 纳米线互连&quot;">​</a></h3><p><strong>Surface-dominant transport in Weyl semimetal NbAs nanowires for next-generation interconnects</strong><em>Science (2026)</em></p><p>铜互连在纳米尺度电阻率因表面散射急剧上升，是芯片继续缩小的硬墙。该工作用热机械纳米模塑（thermomechanical nanomolding）做出单晶 NbAs 纳米线，直径可控至 40 nm，且电阻率<strong>随直径减小而下降</strong>：40 nm 线在室温下为 10.5 ± 1.9 μΩ·cm，比体材料低约 70%。计算把这一反常归因于表面主导导电与有限温度下的长载流子寿命，纳米线与体晶还表现出高击穿电流密度、稳定性与热导。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adx3027" target="_blank" rel="noreferrer">10.1126/science.adx3027</a></p><h3 id="🧲-扭曲菱面石墨烯中的-c-7-3-分数量子陈绝缘体" tabindex="-1">🧲 扭曲菱面石墨烯中的 |C| = 7/3 分数量子陈绝缘体 <a class="header-anchor" href="#🧲-扭曲菱面石墨烯中的-c-7-3-分数量子陈绝缘体" aria-label="Permalink to &quot;🧲 扭曲菱面石墨烯中的 |C| = 7/3 分数量子陈绝缘体&quot;">​</a></h3><p><strong>Fractional high-Chern insulator in twisted rhombohedral graphene</strong><em>Nature (2026)</em></p><p>分数量子陈绝缘体让「无磁场下的分数电荷与任意子」成为可能，但在晶格体系中能否出现超越经典 Jain 序列的新态一直是核心问题。研究者在 Bernal 双层 + 菱面四层石墨烯构成的莫尔平带体系中，于填充因子 ν = 1 及 ν ≈ 3 附近观测到陈数从 |C| = 1 到 |C| = 7 的一系列量子反常霍尔绝缘体。更关键的是在 ν ≈ 2/3 处发现 C = 7/3 的分数量子陈绝缘体——它既不属于 Jain 序列，也超出既有高陈数理论的描述范围。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10762-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10762-7</a></p><h3 id="🧠-树突是并行计算单元-ca3-锥体神经元的独立电压运算" tabindex="-1">🧠 树突是并行计算单元：CA3 锥体神经元的独立电压运算 <a class="header-anchor" href="#🧠-树突是并行计算单元-ca3-锥体神经元的独立电压运算" aria-label="Permalink to &quot;🧠 树突是并行计算单元：CA3 锥体神经元的独立电压运算&quot;">​</a></h3><p><strong>Parallel independent voltage computing along dendrites of CA3 pyramidal neurons</strong><em>Science (2026)</em></p><p>海马 CA3 在导航中居核心地位，但其树突在活体内如何加工信息基本未知。研究者在虚拟现实导航的小鼠中，对 CA3 锥体神经元的树突与胞体同时做电压成像，发现树突树由多个<strong>可独立运算的单元</strong>组成，能依行为条件动态地与胞体活动耦合或解耦。树突活动通过这种条件耦合塑造空间、奖赏与情境的亚细胞表征，空间共调谐的树突在尖波涟漪期间仍保持协调。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aeh9302" target="_blank" rel="noreferrer">10.1126/science.aeh9302</a></p><hr><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="📐-核化线性注意力-用对称锥突破容量墙" tabindex="-1">📐 核化线性注意力：用对称锥突破容量墙 <a class="header-anchor" href="#📐-核化线性注意力-用对称锥突破容量墙" aria-label="Permalink to &quot;📐 核化线性注意力：用对称锥突破容量墙&quot;">​</a></h3><p><strong>Kernelized Linear Attention: Breaking the Capacity Wall with Symmetric Cones</strong><em>arXiv (2026)</em></p><p>线性注意力能常数时间循环推理，但在联想召回上急剧退化。作者把注意力召回形式化为球面填充问题，提出 KATA：用自对偶齐次锥证明注意力权重非负，从第一性原理导出特征映射，并论证秩一 PSD 特征在「容量—干扰」之间取得有利折中。KATA 还免费得到一个无参数的凸输出门，并用 Welch 干扰下界刻画联想容量；在容差高于该下界时，可在不加参数的前提下扩大状态。Triton 实现给出两条工作点：类 FlashAttention 前向约 1.6× 吞吐，精确 O(T) 分块状态形式在 131k token 下达约 11× FlashAttention-2。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.17419" target="_blank" rel="noreferrer">2607.17419</a></p><h3 id="∑-野生数学发现-ai-在-banach-空间理论中给出五个新结果" tabindex="-1">∑ 野生数学发现：AI 在 Banach 空间理论中给出五个新结果 <a class="header-anchor" href="#∑-野生数学发现-ai-在-banach-空间理论中给出五个新结果" aria-label="Permalink to &quot;∑ 野生数学发现：AI 在 Banach 空间理论中给出五个新结果&quot;">​</a></h3><p><strong>Mathematical Discovery in the Wild: AI-Guided Proofs in Banach Space Theory</strong><em>arXiv (2026)</em></p><p>作者考察当前语言模型能否真正参与数学研究：在 Banach 空间理论中，AI 系统为五个新结果给出了关键想法与证明，随后由人类验证与精修。团队还搭建了自动系统，能扫描文献寻找开放问题并规模化尝试求解。结论是双向的——模型确有数学发现潜力，但专家验证仍然不可替代。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.17388" target="_blank" rel="noreferrer">2607.17388</a></p><h3 id="🧾-自改写-lean-证明智能体-与基准共同演化" tabindex="-1">🧾 自改写 Lean 证明智能体：与基准共同演化 <a class="header-anchor" href="#🧾-自改写-lean-证明智能体-与基准共同演化" aria-label="Permalink to &quot;🧾 自改写 Lean 证明智能体：与基准共同演化&quot;">​</a></h3><p><strong>Self-Modifying Lean Proof Agents with Verifier-Grounded Benchmark Coevolution</strong><em>arXiv (2026)</em></p><p>与「造更强的证明器」不同，这条路线问的是：围绕 Lean 的工作流（分解证明义务、用工具与编译器反馈、诊断失败、修复、维护结构化证明上下文）能否被演化而不是被手工设计。系统用一个固定、可信的小运行时包裹完全可变的工区（工作流、提示、工具），并在代际之间让冠军智能体改写任务分布：掌握当前难度后才引入更难义务（mastery-throttled curriculum），再用单锚点重校准保持分数可比。所有演化都被限制在 Lean 验证回路内——无论怎么改写自己，只有产出经可信快照验证的证明才算成功，且每次尝试必须给出机器可读、Lean 落地（grounded）的证明上下文。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.17352" target="_blank" rel="noreferrer">2607.17352</a></p><h3 id="⚙️-war-面向同步智能体-rl-的负载感知-rollout" tabindex="-1">⚙️ WAR：面向同步智能体 RL 的负载感知 rollout <a class="header-anchor" href="#⚙️-war-面向同步智能体-rl-的负载感知-rollout" aria-label="Permalink to &quot;⚙️ WAR：面向同步智能体 RL 的负载感知 rollout&quot;">​</a></h3><p><strong>WAR: Workload-Aware Rollouts for Synchronous Agentic Reinforcement Learning</strong><em>arXiv (2026)</em></p><p>长程 rollout 生成已成为智能体 RL 的主要系统瓶颈：多轮交互让轨迹迅速膨胀到数万 token，同步训练被 rollout 卡死。WAR 的关键观察是「最优 rollout 优化策略取决于运行时负载」：低负载时启用无模型的 SuffixDecoding——复用已完成轨迹的后缀模式作投机草稿，不引入草稿模型、也不与 rollout 争 GPU；高负载时批解码已饱和、投机收益有限，于是把优化重心转向缓存感知调度，按缓存局部性、轨迹进度与服务器负载把请求分布到各副本，减少重复 KV-cache 重算并缓解负载不均。不改 RL 算法本身，长上下文轨迹吞吐在低负载下 1.4×、高负载下最高 1.6×。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.17299" target="_blank" rel="noreferrer">2607.17299</a></p><h3 id="🔍-无损但不免费-消费级硬件上投机解码的解剖" tabindex="-1">🔍 无损但不免费：消费级硬件上投机解码的解剖 <a class="header-anchor" href="#🔍-无损但不免费-消费级硬件上投机解码的解剖" aria-label="Permalink to &quot;🔍 无损但不免费：消费级硬件上投机解码的解剖&quot;">​</a></h3><p><strong>Lossless but Not Free: An Empirical Anatomy of Speculative Decoding on Consumer Hardware</strong><em>arXiv (2026)</em></p><p>单流自回归解码受内存带宽限制：每生成一个 token 要一次完整前向，且前后不能并行。投机解码用草稿模型提出 K 个 token、目标模型一次批量打分，再以拒绝采样在数学上保持目标分布。作者从零实现跨后端（CUDA/MPS/CPU）版本，在 Apple 芯片笔记本上跑五种草稿/目标配置：在最优点 K = 6 得到 1.61× 实测加速，接受率从 K = 1 的 69.7% 降到最优点 37.8%；五种配置里有三种反而<strong>变慢</strong>——要么草稿快不过小目标模型，要么量化 Metal 后端把「并行」验证串行执行，这一效应被单独隔离并量化。分布式等价性用约 9,200 个真实 token 的双样本检验（χ² = 162.5，dof = 200，p = 0.976）与贪心序列完全一致来验证。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.17283" target="_blank" rel="noreferrer">2607.17283</a></p><hr><blockquote><p>📅 日期：2026-07-19 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 期号：（第 ? 期 · 事后重建版）——2026-07 期间的期号序列存在断档，无法可靠反推，故不填精确期号</p></blockquote>',48)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
